window.BRIDGE_PAGE_SOURCES=[{"name": "ch02-reliability-lab.html", "text": "<!doctype html>\n<!--\n  Offline teaching rebuild, 2026-08-02.\n  Source concept: Desktop demo “抗力与荷载联合概率分布可视化（含蒙特卡洛模拟）.html”.\n  Source SHA-256: 9325EB6DB916C5F0DE49569F5B0F543BB9C25B3B688B1A97A9550D1CC3DE522A.\n  The original file remains untouched; probability formulas and sampling were independently corrected here.\n-->\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>抗力—作用效应与失效概率</title>\n  <link rel=\"icon\" href=\"data:,\">\n  <script>if(new URLSearchParams(location.search).get('skin')==='first-part')document.documentElement.classList.add('bridge-visual-first-part')</script>\n  <style>\n    :root {\n      color-scheme: light;\n      --paper: #f5f8f8;\n      --surface: #ffffff;\n      --ink: #102a36;\n      --muted: #61747d;\n      --line: #cfdbde;\n      --line-strong: #9fb3b9;\n      --cyan: #197f96;\n      --cyan-soft: #dceff2;\n      --amber: #d88b24;\n      --amber-soft: #fff0d6;\n      --coral: #bb5146;\n      --coral-soft: #f8dfdc;\n      --shadow: 0 18px 50px rgba(16, 42, 54, .09);\n      font-family: \"Microsoft YaHei\", \"PingFang SC\", \"Noto Sans CJK SC\", system-ui, sans-serif;\n    }\n\n    * { box-sizing: border-box; }\n    html { background: var(--paper); }\n    body {\n      margin: 0;\n      min-width: 0;\n      overflow-x: clip;\n      color: var(--ink);\n      background:\n        linear-gradient(rgba(25, 127, 150, .035) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(25, 127, 150, .035) 1px, transparent 1px),\n        var(--paper);\n      background-size: 24px 24px;\n    }\n\n    button, input, select { font: inherit; }\n    button, input[type=\"radio\"], input[type=\"range\"], select { cursor: pointer; }\n    button:focus-visible, input:focus-visible, select:focus-visible, summary:focus-visible {\n      outline: 3px solid rgba(25, 127, 150, .32);\n      outline-offset: 3px;\n    }\n\n    .lab-shell {\n      width: min(100%, 1120px);\n      margin: 0 auto;\n      padding: clamp(18px, 3.5vw, 42px) clamp(14px, 3vw, 34px) 34px;\n    }\n\n    .masthead {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) auto;\n      gap: 24px;\n      align-items: end;\n      padding-bottom: 22px;\n      border-bottom: 1px solid var(--line-strong);\n    }\n    .eyebrow {\n      margin: 0 0 7px;\n      color: var(--cyan);\n      font-size: 12px;\n      font-weight: 700;\n      letter-spacing: .14em;\n    }\n    h1 {\n      margin: 0;\n      max-width: 780px;\n      font-family: \"STKaiti\", \"KaiTi\", serif;\n      font-size: clamp(25px, 4.2vw, 40px);\n      font-weight: 600;\n      line-height: 1.22;\n      letter-spacing: .01em;\n    }\n    .lead {\n      max-width: 720px;\n      margin: 11px 0 0;\n      color: var(--muted);\n      font-size: 14px;\n      line-height: 1.75;\n    }\n    .offline-mark {\n      align-self: start;\n      border: 1px solid var(--line-strong);\n      padding: 7px 10px;\n      color: var(--muted);\n      background: rgba(255, 255, 255, .7);\n      font-size: 11px;\n      letter-spacing: .08em;\n      white-space: nowrap;\n    }\n\n    .lab-zone {\n      position: relative;\n      padding: 28px 0 30px 58px;\n      border-bottom: 1px solid var(--line);\n    }\n    .lab-zone::before {\n      content: attr(data-zone);\n      position: absolute;\n      top: 28px;\n      left: 0;\n      z-index: 1;\n      display: grid;\n      width: 34px;\n      height: 34px;\n      place-items: center;\n      border: 1px solid var(--cyan);\n      border-radius: 50%;\n      color: var(--cyan);\n      background: var(--paper);\n      font: 700 13px/1 system-ui, sans-serif;\n    }\n    .lab-zone:not(:last-child)::after {\n      content: \"\";\n      position: absolute;\n      top: 61px;\n      bottom: -1px;\n      left: 16px;\n      width: 1px;\n      background: linear-gradient(var(--cyan), var(--line));\n    }\n    .zone-kicker {\n      margin: 0 0 4px;\n      color: var(--cyan);\n      font-size: 11px;\n      font-weight: 700;\n      letter-spacing: .12em;\n    }\n    h2 {\n      margin: 0 0 12px;\n      font-family: \"STKaiti\", \"KaiTi\", serif;\n      font-size: clamp(20px, 3vw, 27px);\n      font-weight: 600;\n      line-height: 1.35;\n    }\n    .zone-intro {\n      max-width: 820px;\n      margin: 0 0 17px;\n      color: var(--muted);\n      font-size: 14px;\n      line-height: 1.75;\n    }\n\n    fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }\n    .prediction-write { max-width: 860px; }\n    .prediction-write label { display: block; margin-bottom: 6px; color: var(--ink); font-size: 13px; font-weight: 700; }\n    .prediction-write textarea { display: block; width: 100%; min-height: 64px; resize: vertical; border: 1px solid var(--line-strong); padding: 10px 12px; background: rgba(255,255,255,.9); color: var(--ink); font: inherit; font-size: 13px; line-height: 1.6; }\n    .prediction-write textarea:focus-visible { outline: 3px solid rgba(25,133,150,.22); outline-offset: 2px; border-color: var(--cyan); }\n    .prediction-action { display: flex; align-items: center; gap: 13px; margin-top: 13px; flex-wrap: wrap; }\n    .primary, .secondary, .preset {\n      min-height: 44px;\n      border: 1px solid var(--cyan);\n      padding: 9px 14px;\n      background: var(--ink);\n      color: #fff;\n      font-weight: 700;\n    }\n    .primary[disabled] { cursor: not-allowed; opacity: .42; }\n    .secondary, .preset {\n      border-color: var(--line-strong);\n      background: var(--surface);\n      color: var(--ink);\n      font-weight: 600;\n    }\n    .preset:hover, .secondary:hover { border-color: var(--cyan); background: var(--cyan-soft); }\n    .prediction-note { color: var(--muted); font-size: 12px; }\n    .prediction-note[data-ready=\"true\"] { color: var(--cyan); font-weight: 700; }\n    .prediction-visual { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; max-width: 860px; }\n    .prediction-card { min-width: 0; border: 1px solid var(--line-strong); padding: 12px; background: rgba(255,255,255,.86); color: var(--ink); text-align: left; box-shadow: 0 8px 22px rgba(16,42,54,.05); }\n    .prediction-card:hover { border-color: var(--cyan); background: var(--surface); }\n    .prediction-card.is-selected { border-color: var(--cyan); box-shadow: inset 0 0 0 2px var(--cyan), 0 10px 26px rgba(16,42,54,.08); }\n    .prediction-card__head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 5px; }\n    .prediction-card__head b { color: var(--ink); font-size: 15px; }\n    .prediction-card__head span { color: var(--muted); font-size: 11px; }\n    .prediction-card svg { display: block; width: 100%; height: 92px; border-top: 1px solid var(--line); }\n    .prediction-card .base { stroke: #9fb3b9; stroke-width: 1; }\n    .prediction-card .r-curve, .prediction-card .s-curve { fill: none; stroke-width: 3; stroke-linecap: round; }\n    .prediction-card .r-curve { stroke: var(--cyan); }\n    .prediction-card .s-curve { stroke: var(--coral); }\n    .prediction-note { max-width: 860px; margin: 9px 0 0; }\n\n    .surface-panel { margin-bottom: 14px; }\n    .advanced-views {\n      margin: 14px 0 0;\n      border: 1px solid var(--line-strong);\n      background: rgba(255,255,255,.72);\n    }\n    .advanced-views > summary {\n      min-height: 52px;\n      padding: 14px 16px;\n      cursor: pointer;\n      color: var(--ink);\n      font-size: 13px;\n      font-weight: 700;\n    }\n    .advanced-views > summary span { display: block; margin-top: 3px; color: var(--muted); font-size: 11px; font-weight: 400; }\n    .advanced-views[open] > summary { border-bottom: 1px solid var(--line); }\n    .advanced-views__body { padding: 14px; }\n    .surface-stage {\n      position: relative;\n      min-height: 300px;\n      border-top: 1px solid var(--line);\n      background:\n        radial-gradient(circle at 50% 35%, rgba(25,127,150,.08), transparent 38%),\n        linear-gradient(#fbfdfd, #eef4f5);\n    }\n    .surface-stage canvas {\n      display: block;\n      width: 100%;\n      height: clamp(300px, 48vw, 520px);\n      cursor: grab;\n      touch-action: none;\n      user-select: none;\n    }\n    .surface-stage canvas.is-dragging { cursor: grabbing; }\n    .surface-hud {\n      position: absolute;\n      z-index: 2;\n      top: 10px;\n      right: 10px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      max-width: calc(100% - 20px);\n      border: 1px solid rgba(97,116,125,.28);\n      padding: 5px 6px 5px 10px;\n      background: rgba(255,255,255,.88);\n      box-shadow: 0 5px 18px rgba(16,42,54,.08);\n      backdrop-filter: blur(8px);\n      color: var(--muted);\n      font-size: 11px;\n      pointer-events: none;\n    }\n    .surface-hud button {\n      min-height: 44px;\n      border: 1px solid var(--line-strong);\n      padding: 6px 10px;\n      background: var(--surface);\n      color: var(--ink);\n      font: inherit;\n      font-weight: 700;\n      pointer-events: auto;\n    }\n    .surface-hud button:hover { border-color: var(--cyan); background: var(--cyan-soft); }\n    .scene-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 14px;\n    }\n    .plot-panel {\n      min-width: 0;\n      border: 1px solid var(--line);\n      background: var(--surface);\n      box-shadow: var(--shadow);\n    }\n    .plot-head { padding: 14px 16px 0; }\n    .plot-head h3 { margin: 0; font-size: 14px; }\n    .plot-head p { margin: 5px 0 0; color: var(--muted); font-size: 11px; line-height: 1.55; }\n    svg { display: block; width: 100%; height: auto; overflow: visible; }\n    .plot-note {\n      display: flex;\n      min-height: 38px;\n      align-items: center;\n      justify-content: space-between;\n      gap: 10px;\n      border-top: 1px solid var(--line);\n      padding: 8px 13px;\n      color: var(--muted);\n      font-size: 10px;\n    }\n    .legend { display: flex; gap: 12px; flex-wrap: wrap; }\n    .legend span::before { content: \"\"; display: inline-block; width: 9px; height: 9px; margin-right: 5px; }\n    .legend .safe::before { border-radius: 50%; background: var(--cyan); }\n    .legend .fail::before { background: var(--coral); transform: rotate(45deg); }\n\n    .control-toolbar { display: flex; gap: 8px; margin: 0 0 17px; flex-wrap: wrap; }\n    .preset { min-height: 44px; padding: 7px 11px; font-size: 12px; }\n    .control-grid {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 12px;\n    }\n    .control {\n      min-width: 0;\n      border-top: 2px solid var(--line);\n      padding: 11px 10px 9px;\n      background: rgba(255, 255, 255, .74);\n    }\n    .control label, .control .label-row {\n      display: flex;\n      align-items: baseline;\n      justify-content: space-between;\n      gap: 8px;\n      color: var(--ink);\n      font-size: 12px;\n      font-weight: 700;\n    }\n    output { color: var(--cyan); font-variant-numeric: tabular-nums; white-space: nowrap; }\n    input[type=\"range\"] { width: 100%; height: 28px; margin: 6px 0 0; accent-color: var(--cyan); }\n    .range-hints { display: flex; justify-content: space-between; color: var(--muted); font-size: 9px; }\n    select, input[type=\"number\"] {\n      width: 100%;\n      min-height: 44px;\n      margin-top: 7px;\n      border: 1px solid var(--line-strong);\n      border-radius: 0;\n      padding: 7px 9px;\n      color: var(--ink);\n      background: #fff;\n    }\n    .seed-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px; align-items: end; }\n    .seed-row button { min-height: 44px; margin-top: 7px; padding-inline: 10px; }\n    .advanced {\n      margin-top: 12px;\n      border: 1px solid var(--line);\n      background: rgba(255, 255, 255, .72);\n    }\n    .advanced summary { min-height: 44px; padding: 12px 14px; cursor: pointer; color: var(--ink); font-size: 12px; font-weight: 700; }\n    .advanced-inner { display: grid; grid-template-columns: minmax(220px, .8fr) minmax(0, 1.2fr); gap: 18px; border-top: 1px solid var(--line); padding: 13px 14px; }\n    .advanced p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.7; }\n    .principle {\n      border-left: 5px solid var(--amber);\n      padding: 15px 18px;\n      background: var(--amber-soft);\n    }\n    .principle b { display: block; margin-bottom: 6px; font: 600 21px/1.4 \"STKaiti\", \"KaiTi\", serif; }\n    .principle p { margin: 0; font-size: 13px; line-height: 1.75; }\n    .prediction-return { margin-top: 8px !important; color: #725324; }\n    .metrics {\n      display: grid;\n      grid-template-columns: repeat(4, minmax(0, 1fr));\n      gap: 1px;\n      margin-top: 14px;\n      border: 1px solid var(--line);\n      background: var(--line);\n    }\n    .metric { min-width: 0; padding: 13px 14px; background: var(--surface); }\n    .metric span { display: block; min-height: 2.8em; color: var(--muted); font-size: 10px; line-height: 1.4; }\n    .metric strong { display: block; margin-top: 4px; color: var(--ink); font-size: clamp(17px, 2.4vw, 24px); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }\n    .metric.theory { box-shadow: inset 0 3px var(--cyan); }\n    .metric.sample { box-shadow: inset 0 3px var(--coral); }\n    .sample-explain { margin: 11px 0 0; color: var(--muted); font-size: 12px; line-height: 1.7; }\n    .sample-explain strong { color: var(--ink); }\n    .formula-panel {\n      margin-top: 18px;\n      border-top: 1px solid var(--line-strong);\n      padding-top: 16px;\n    }\n    .formula-panel h3 { margin: 0 0 9px; font-size: 14px; }\n    .formula-line {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 4px 20px;\n      max-width: 100%;\n      padding: 8px 10px;\n      color: var(--ink);\n      background: var(--cyan-soft);\n      font: 600 13px/1.65 \"Cambria Math\", \"Times New Roman\", serif;\n    }\n    .formula-line span {\n      white-space: nowrap;\n    }\n    .formula-panel p { margin: 9px 0 0; color: var(--muted); font-size: 12px; line-height: 1.7; }\n    .permission {\n      display: grid;\n      grid-template-columns: auto minmax(0, 1fr);\n      gap: 0;\n      margin: 18px 0 0;\n      border: 1px solid var(--line-strong);\n      background: var(--surface);\n      font-size: 11px;\n      line-height: 1.55;\n    }\n    .permission dt, .permission dd { margin: 0; padding: 8px 10px; border-bottom: 1px solid var(--line); }\n    .permission dt { color: var(--cyan); font-weight: 700; white-space: nowrap; }\n    .permission dd { color: var(--muted); }\n    .permission dt:nth-last-of-type(1), .permission dd:last-child { border-bottom: 0; }\n    .technical-notes { margin-top: 16px; }\n    .technical-notes__body { border-top: 1px solid var(--line); padding: 14px; }\n    .technical-notes .formula-panel { margin-top: 0; border-top: 0; padding-top: 0; }\n    .bridge-visual-first-part .first-part-advanced { display: none !important; }\n    .bridge-visual-first-part .lab-shell { padding-top: 24px; padding-bottom: 22px; }\n    .bridge-visual-first-part .lab-zone { padding-top: 22px; padding-bottom: 23px; }\n    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; }\n    [hidden] { display: none !important; }\n\n    @media (max-width: 860px) {\n      .masthead { grid-template-columns: 1fr; gap: 13px; }\n      .offline-mark { justify-self: start; }\n      .scene-grid { grid-template-columns: 1fr; }\n      .control-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n      .metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n    }\n    @media (max-width: 560px) {\n      .lab-shell { padding: 15px 12px 24px; }\n      .lab-zone { padding: 23px 0 25px 42px; }\n      .lab-zone::before { top: 23px; width: 28px; height: 28px; font-size: 11px; }\n      .lab-zone:not(:last-child)::after { top: 50px; left: 13px; }\n      .control-grid, .advanced-inner { grid-template-columns: 1fr; }\n      .plot-head { padding: 12px 12px 0; }\n      .surface-stage { min-height: 270px; }\n      .surface-stage canvas { height: 270px; }\n      .plot-note { align-items: flex-start; flex-direction: column; }\n      .metrics { grid-template-columns: 1fr; }\n      .prediction-visual { grid-template-columns: 1fr; }\n      .metric span { min-height: 0; }\n      .permission { grid-template-columns: 1fr; }\n      .permission dt { border-bottom: 0; padding-bottom: 2px; }\n      .permission dd { padding-top: 2px; }\n      .permission dt:nth-last-of-type(1) { border-bottom: 0; }\n    }\n    @media (prefers-reduced-motion: reduce) {\n      *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; }\n    }\n  </style>\n</head>\n<body>\n  <main class=\"lab-shell\">\n    <header class=\"masthead\">\n      <div>\n        <p class=\"eyebrow\">作用与可靠度 · 参数实验</p>\n        <h1>抗力—作用效应与失效概率</h1>\n        <p class=\"lead\">抗力与作用效应均具有不确定性。图中同时显示边缘分布、联合密度、极限状态边界和失效域，并给出参数变化对应的失效概率与可靠指标。</p>\n      </div>\n      <div class=\"offline-mark\">完全离线 · 固定随机种子</div>\n    </header>\n\n    <section class=\"lab-zone lab-question\" data-zone=\"1\" data-learning-cycle-mount>\n      <p class=\"zone-kicker\">基准参数</p>\n      <h2>均值与离散程度共同决定失效域中的概率质量</h2>\n      <p class=\"zone-intro\">初始参数取平均抗力 10、平均作用效应 6，标准差分别为 1.50 和 1.20。后续图形在同一坐标、同一失效边界下显示均值、标准差和相关系数变化，所有结论均以计算结果为依据。</p>\n    </section>\n\n    <section class=\"lab-zone lab-scene\" data-zone=\"2\" data-lab-scene>\n      <p class=\"zone-kicker\">概率分布</p>\n      <h2>边缘分布、联合密度与极限状态边界</h2>\n      <article class=\"plot-panel surface-panel\">\n        <div class=\"plot-head\">\n          <h3>抗力与作用效应的边缘分布</h3>\n          <p>青色曲线表示抗力，红色曲线表示作用效应。抗力分布左尾与作用效应分布右尾共同影响失效概率。C50 混凝土强度标准值的保证率用于说明材料强度取值，不等同于结构可靠度。</p>\n        </div>\n        <svg id=\"marginalPlot\" viewBox=\"0 0 900 360\" role=\"img\" aria-labelledby=\"marginalTitle marginalDesc\">\n          <title id=\"marginalTitle\">抗力和荷载的一维概率密度分布</title>\n          <desc id=\"marginalDesc\">抗力分布的标准值位于均值左侧，右侧面积为百分之九十五；荷载与抗力的尾部相遇时可能失效。</desc>\n        </svg>\n        <div class=\"plot-note\">\n          <div class=\"legend\"><span class=\"safe\">抗力 R</span><span class=\"fail\">荷载 S</span></div>\n          <span>一维曲线的面积为 1；特征值右侧的青色面积为 95%</span>\n        </div>\n      </article>\n      <details class=\"advanced-views\" id=\"advancedViews\">\n        <summary>联合分布及等价表示<span>显示二维样本、可旋转联合密度曲面和 R−S 差值分布</span></summary>\n        <div class=\"advanced-views__body\">\n      <article class=\"plot-panel surface-panel\">\n        <div class=\"plot-head\">\n          <h3>联合概率密度曲面</h3>\n          <p>曲面峰值对应概率密度较高的参数组合；红色区域表示联合分布越过 R = S 极限状态边界的尾部。</p>\n        </div>\n        <div class=\"surface-stage\">\n          <canvas id=\"surfacePlot\" role=\"img\" tabindex=\"0\" aria-label=\"可旋转的抗力与荷载联合概率密度三维地形图。拖动旋转，滚轮或加减键缩放，方向键微调视角；青色是 R 大于等于 S 的安全侧，红色是 R 小于 S 的失效侧。\"></canvas>\n          <div class=\"surface-hud\"><span>拖动旋转 · 滚轮缩放 · 双击复位</span><button id=\"resetSurfaceView\" type=\"button\">复位视角</button></div>\n        </div>\n        <div class=\"plot-note\">\n          <div class=\"legend\"><span class=\"safe\">R ≥ S：安全侧</span><span class=\"fail\">R &lt; S：失效侧</span></div>\n          <span>联合密度曲面、平面等高线与差值分布表示同一概率模型</span>\n        </div>\n      </article>\n      <div class=\"scene-grid\" id=\"sceneGrid\">\n        <article class=\"plot-panel\">\n          <div class=\"plot-head\">\n            <h3>联合密度等高线与随机样本</h3>\n            <p>横轴为作用效应，纵轴为抗力；椭圆表示联合概率密度等高线，R = S 直线下方为失效域。</p>\n          </div>\n          <svg id=\"jointPlot\" viewBox=\"0 0 600 420\" role=\"img\" aria-labelledby=\"jointTitle jointDesc\">\n            <title id=\"jointTitle\">抗力与荷载随机样本散点图</title>\n            <desc id=\"jointDesc\">安全样本位于抗力大于等于荷载的一侧，失效样本位于抗力小于荷载的一侧。</desc>\n          </svg>\n          <div class=\"plot-note\">\n            <div class=\"legend\"><span class=\"safe\">R ≥ S：安全域</span><span class=\"fail\">R &lt; S：失效域</span></div>\n            <span id=\"shownPoints\">—</span>\n          </div>\n        </article>\n        <article class=\"plot-panel\">\n          <div class=\"plot-head\">\n            <h3>功能函数 Z = R − S 的分布</h3>\n            <p>横轴为抗力与作用效应之差。Z &lt; 0 与联合分布中 R = S 直线下方的失效域相对应。</p>\n          </div>\n          <svg id=\"gapPlot\" viewBox=\"0 0 600 420\" role=\"img\" aria-labelledby=\"gapTitle gapDesc\">\n            <title id=\"gapTitle\">抗力减荷载的概率密度图</title>\n            <desc id=\"gapDesc\">零左侧的阴影面积是理论失效概率，零右侧是抗力大于等于荷载的区域。</desc>\n          </svg>\n          <div class=\"plot-note\"><span>联合分布中的失效样本与差值分布中 Z &lt; 0 的概率质量相互对应。</span></div>\n        </article>\n      </div>\n        </div>\n      </details>\n    </section>\n\n    <section class=\"lab-zone lab-controls\" data-zone=\"3\" data-lab-controls>\n      <p class=\"zone-kicker\">单参数对比</p>\n      <h2>参数变化与失效概率</h2>\n      <p class=\"zone-intro\">“波动减半”预设用于与初始状态对比。固定随机种子使两个参数情形采用同一组标准随机数，减少抽样差异对参数效应判断的干扰。</p>\n      <div id=\"controlsWrap\">\n        <div class=\"control-toolbar\" aria-label=\"参数情形\">\n          <button class=\"preset\" type=\"button\" data-preset=\"stable\">波动减半</button>\n          <button class=\"preset\" type=\"button\" data-preset=\"default\">恢复初始参数</button>\n          <button class=\"preset first-part-advanced\" type=\"button\" data-preset=\"close\">缩小均值差</button>\n          <button class=\"preset first-part-advanced\" type=\"button\" data-preset=\"together\">设置正相关</button>\n        </div>\n        <fieldset id=\"parameterFields\">\n          <legend class=\"sr-only\">抗力、荷载和抽样参数</legend>\n          <div class=\"control-grid\">\n            <div class=\"control first-part-advanced\">\n              <label for=\"meanR\"><span>抗力的平均水平 μ<sub>R</sub></span><output id=\"meanROut\">10.0</output></label>\n              <input id=\"meanR\" type=\"range\" min=\"5\" max=\"15\" step=\"0.1\" value=\"10\">\n              <div class=\"range-hints\"><span>5</span><span>15</span></div>\n            </div>\n            <div class=\"control\">\n              <label for=\"stdR\"><span>抗力的波动 σ<sub>R</sub></span><output id=\"stdROut\">1.50</output></label>\n              <input id=\"stdR\" type=\"range\" min=\"0.2\" max=\"3\" step=\"0.05\" value=\"1.5\">\n              <div class=\"range-hints\"><span>0.20</span><span>3.00</span></div>\n            </div>\n            <div class=\"control first-part-advanced\">\n              <label for=\"meanS\"><span>荷载的平均水平 μ<sub>S</sub></span><output id=\"meanSOut\">6.0</output></label>\n              <input id=\"meanS\" type=\"range\" min=\"5\" max=\"15\" step=\"0.1\" value=\"6\">\n              <div class=\"range-hints\"><span>5</span><span>15</span></div>\n            </div>\n            <div class=\"control\">\n              <label for=\"stdS\"><span>荷载的波动 σ<sub>S</sub></span><output id=\"stdSOut\">1.20</output></label>\n              <input id=\"stdS\" type=\"range\" min=\"0.2\" max=\"3\" step=\"0.05\" value=\"1.2\">\n              <div class=\"range-hints\"><span>0.20</span><span>3.00</span></div>\n            </div>\n            <div class=\"control first-part-advanced\">\n              <label for=\"sampleN\">随机样本数</label>\n              <select id=\"sampleN\">\n                <option value=\"500\">500</option>\n                <option value=\"1000\" selected>1,000</option>\n                <option value=\"5000\">5,000</option>\n                <option value=\"20000\">20,000</option>\n              </select>\n            </div>\n            <div class=\"control first-part-advanced\">\n              <label for=\"seed\">随机种子</label>\n              <div class=\"seed-row\">\n                <input id=\"seed\" type=\"number\" min=\"1\" max=\"999999\" step=\"1\" value=\"240325\" inputmode=\"numeric\">\n                <button class=\"secondary\" id=\"nextSeed\" type=\"button\">更新随机种子</button>\n              </div>\n            </div>\n          </div>\n          <details class=\"advanced\">\n            <summary>进阶参数：抗力与作用效应的相关性</summary>\n            <div class=\"advanced-inner\">\n              <div class=\"control\">\n                <label for=\"rho\"><span>相关系数 ρ</span><output id=\"rhoOut\">0.00</output></label>\n                <input id=\"rho\" type=\"range\" min=\"-0.8\" max=\"0.8\" step=\"0.05\" value=\"0\">\n                <div class=\"range-hints\"><span>−0.80</span><span>彼此独立 0</span><span>+0.80</span></div>\n              </div>\n              <p>ρ = 0 表示本页基准情形中的两个随机变量相互独立；ρ &gt; 0 表示正相关，ρ &lt; 0 表示负相关。相关性通过差值方差影响可靠指标与失效概率，不能脱离均值、标准差和极限状态单独判断其利弊。</p>\n            </div>\n          </details>\n        </fieldset>\n      </div>\n    </section>\n\n    <section class=\"lab-zone lab-explanation\" data-zone=\"4\" data-learning-result-mount>\n      <p class=\"zone-kicker\">结果解释</p>\n      <h2>可靠指标与失效概率</h2>\n      <div class=\"principle\">\n        <b>可靠度由均值差和随机变量的离散程度共同决定。</b>\n        <p>平均抗力大于平均作用效应只反映两个分布中心的相对位置；分布尾部仍可能进入失效域。离散程度增大时，越过极限状态边界的概率质量可能增加，因此应同时考察均值、标准差与相关性。</p>\n        <p>同一分析框架可用于其他“能力—需求”问题，但其概率分布、相关性和越界后果必须依据相应对象重新确定。</p>\n        <p class=\"prediction-return\" id=\"predictionReturn\">保持均值不变时，增大标准差会加宽分布，并改变越过极限状态边界的概率质量。</p>\n      </div>\n\n      <div class=\"metrics\" aria-live=\"polite\">\n        <div class=\"metric theory\"><span>可靠指标 β</span><strong id=\"betaValue\">—</strong></div>\n        <div class=\"metric theory\"><span>理论失效概率 P<sub>f</sub></span><strong id=\"pfValue\">—</strong></div>\n        <div class=\"metric sample\"><span>样本失效次数</span><strong id=\"sampleValue\">—</strong></div>\n        <div class=\"metric sample\"><span>样本比例置信区间</span><strong id=\"ciValue\">—</strong></div>\n      </div>\n      <p class=\"sample-explain\" id=\"sampleExplain\">理论值描述给定分布；样本值只描述这一批有限抽样。样本数很少时，即使理论概率不为零，也可能一次都没有抽到。</p>\n\n      <details class=\"advanced technical-notes\">\n        <summary>进阶：公式和这个模型的适用边界</summary>\n        <div class=\"technical-notes__body\">\n          <div class=\"formula-panel\">\n            <h3>功能函数、可靠指标与失效概率</h3>\n            <div class=\"formula-line\"><span>Z = R − S</span><span>σ<sub>Z</sub> = √(σ<sub>R</sub>² + σ<sub>S</sub>² − 2ρσ<sub>R</sub>σ<sub>S</sub>)</span><span>β = (μ<sub>R</sub> − μ<sub>S</sub>) / σ<sub>Z</sub></span><span>P<sub>f</sub> = Φ(−β)</span></div>\n            <p id=\"formulaNote\">初始情形取 ρ = 0，R 与 S 相互独立，所以 σ<sub>Z</sub> = √(σ<sub>R</sub>² + σ<sub>S</sub>²)。“可靠指标 β”就是均值差里能放下多少个“差值的标准差”；P<sub>f</sub> 是 Z &lt; 0 的理论概率。</p>\n          </div>\n          <dl class=\"permission\" aria-label=\"模型权限\">\n            <dt>保留</dt><dd>正态抗力 R、正态荷载 S、二者相关性以及 R &lt; S 这一极限状态。</dd>\n            <dt>舍弃</dt><dd>非正态尾部、随时间和空间变化、多个失效模式以及失效后果。</dd>\n            <dt>可以回答</dt><dd>均值、波动、相关性和样本数怎样改变理论概率与抽样不确定性。</dd>\n            <dt>不可用于</dt><dd>给真实桥梁定可靠等级、代替规范验算，或据此作工程安全决定。</dd>\n          </dl>\n        </div>\n      </details>\n      <p class=\"sr-only\" id=\"liveSummary\" aria-live=\"polite\"></p>\n    </section>\n  </main>\n\n  <script>\n    (() => {\n      \"use strict\";\n\n      const $ = (id) => document.getElementById(id);\n      const defaultSurfaceView = { yaw: Math.PI / 4, pitch: .62, zoom: 1 };\n      const state = {\n        started: true,\n        framePending: false,\n        surfacePending: false,\n        surfaceView: { ...defaultSurfaceView },\n        surfaceDrag: null\n      };\n      const parameterIds = [\"meanR\", \"stdR\", \"meanS\", \"stdS\", \"rho\", \"sampleN\", \"seed\"];\n\n      function clamp(value, min, max) { return Math.max(min, Math.min(max, value)); }\n      function fmt(value, digits = 2) {\n        if (Math.abs(value) < Math.pow(10, -digits) / 2) value = 0;\n        return Number(value).toLocaleString(\"zh-CN\", { minimumFractionDigits: digits, maximumFractionDigits: digits });\n      }\n      function probabilityText(p) {\n        const percent = p * 100;\n        if (p === 0) return \"0%\";\n        if (percent < 0.0001) return percent.toExponential(2) + \"%\";\n        if (percent < 0.01) return fmt(percent, 4) + \"%\";\n        if (percent < 1) return fmt(percent, 3) + \"%\";\n        return fmt(percent, 2) + \"%\";\n      }\n      function erf(x) {\n        const sign = x < 0 ? -1 : 1;\n        const a = Math.abs(x);\n        const t = 1 / (1 + 0.3275911 * a);\n        const y = 1 - (((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t) * Math.exp(-a * a);\n        return sign * y;\n      }\n      function normalCDF(x) {\n        if (x === 0) return 0.5;\n        if (x <= -8) return 0;\n        if (x >= 8) return 1;\n        return 0.5 * (1 + erf(x / Math.SQRT2));\n      }\n      function normalPDF(x, mean, sd) {\n        const z = (x - mean) / sd;\n        return Math.exp(-0.5 * z * z) / (sd * Math.sqrt(2 * Math.PI));\n      }\n      function mulberry32(seed) {\n        let a = seed >>> 0;\n        return function() {\n          a |= 0;\n          a = a + 0x6D2B79F5 | 0;\n          let t = Math.imul(a ^ a >>> 15, 1 | a);\n          t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n          return ((t ^ t >>> 14) >>> 0) / 4294967296;\n        };\n      }\n      function normalPair(random) {\n        const u1 = Math.max(random(), Number.EPSILON);\n        const u2 = random();\n        const radius = Math.sqrt(-2 * Math.log(u1));\n        const angle = 2 * Math.PI * u2;\n        return [radius * Math.cos(angle), radius * Math.sin(angle)];\n      }\n      function wilsonInterval(successes, n) {\n        const z = 1.959963984540054;\n        const p = successes / n;\n        const z2 = z * z;\n        const denominator = 1 + z2 / n;\n        const center = (p + z2 / (2 * n)) / denominator;\n        const half = z * Math.sqrt(p * (1 - p) / n + z2 / (4 * n * n)) / denominator;\n        const low = clamp(center - half, 0, 1);\n        return [low < 1e-15 ? 0 : low, clamp(center + half, 0, 1)];\n      }\n      function params() {\n        return {\n          meanR: +$(\"meanR\").value,\n          stdR: +$(\"stdR\").value,\n          meanS: +$(\"meanS\").value,\n          stdS: +$(\"stdS\").value,\n          rho: +$(\"rho\").value,\n          n: +$(\"sampleN\").value,\n          seed: clamp(Math.round(+$(\"seed\").value || 1), 1, 999999)\n        };\n      }\n      function theory(p) {\n        const meanZ = p.meanR - p.meanS;\n        const varianceZ = p.stdR * p.stdR + p.stdS * p.stdS - 2 * p.rho * p.stdR * p.stdS;\n        const stdZ = Math.sqrt(Math.max(varianceZ, Number.EPSILON));\n        const beta = meanZ / stdZ;\n        const pf = normalCDF(-beta);\n        return { meanZ, stdZ, beta, pf };\n      }\n      function sample(p) {\n        const random = mulberry32(p.seed);\n        const root = Math.sqrt(Math.max(0, 1 - p.rho * p.rho));\n        const limit = Math.min(p.n, 1200);\n        const shown = [];\n        let failures = 0;\n        for (let i = 0; i < p.n; i++) {\n          const [z1, z2] = normalPair(random);\n          const r = p.meanR + p.stdR * z1;\n          const s = p.meanS + p.stdS * (p.rho * z1 + root * z2);\n          const failed = r < s;\n          if (failed) failures++;\n          if (i < limit) shown.push({ r, s, failed });\n        }\n        return { failures, shown, ci: wilsonInterval(failures, p.n) };\n      }\n\n      function jointDensity(p, s, r) {\n        const oneMinus = Math.max(1 - p.rho * p.rho, Number.EPSILON);\n        const zs = (s - p.meanS) / p.stdS;\n        const zr = (r - p.meanR) / p.stdR;\n        const exponent = -(zs * zs - 2 * p.rho * zs * zr + zr * zr) / (2 * oneMinus);\n        return Math.exp(exponent) / (2 * Math.PI * p.stdS * p.stdR * Math.sqrt(oneMinus));\n      }\n\n      function renderMarginals(p) {\n        const svg = $(\"marginalPlot\");\n        const width = 900, height = 360;\n        const margin = { left: 58, right: 32, top: 38, bottom: 55 };\n        const plotW = width - margin.left - margin.right;\n        const plotH = height - margin.top - margin.bottom;\n        const lower = Math.min(p.meanR - 4.2 * p.stdR, p.meanS - 4.2 * p.stdS);\n        const upper = Math.max(p.meanR + 4.2 * p.stdR, p.meanS + 4.2 * p.stdS);\n        const peak = Math.max(normalPDF(p.meanR, p.meanR, p.stdR), normalPDF(p.meanS, p.meanS, p.stdS)) * 1.12;\n        const x = value => margin.left + (value - lower) / (upper - lower) * plotW;\n        const y = value => margin.top + plotH - value / peak * plotH;\n        const baseY = margin.top + plotH;\n        const makePath = (mean, sd, start = lower, end = upper, close = false) => {\n          const parts = [];\n          const count = 180;\n          for (let i = 0; i <= count; i++) {\n            const value = start + (end - start) * i / count;\n            parts.push(`${i ? \"L\" : \"M\"}${x(value).toFixed(2)},${y(normalPDF(value, mean, sd)).toFixed(2)}`);\n          }\n          if (close) parts.push(`L${x(end).toFixed(2)},${baseY} L${x(start).toFixed(2)},${baseY} Z`);\n          return parts.join(\" \");\n        };\n        const rk = p.meanR - 1.64485362695147 * p.stdR;\n        const ticks = Array.from({ length: 6 }, (_, i) => lower + (upper - lower) * i / 5);\n        svg.innerHTML = `\n          <defs>\n            <linearGradient id=\"r95Fill\" x1=\"0\" x2=\"1\"><stop offset=\"0\" stop-color=\"#82c8d0\" stop-opacity=\".24\"/><stop offset=\"1\" stop-color=\"#197f96\" stop-opacity=\".08\"/></linearGradient>\n            <pattern id=\"r5Hatch\" width=\"8\" height=\"8\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(35)\"><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"8\" stroke=\"#bb5146\" stroke-opacity=\".42\" stroke-width=\"2\"/></pattern>\n            <marker id=\"arrowCoral\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#bb5146\"/></marker>\n            <marker id=\"arrowCyan\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#197f96\"/></marker>\n          </defs>\n          <style>\n            .m-grid{stroke:#e0e7e9;stroke-width:1}.m-axis{stroke:#61747d;stroke-width:1.3}.m-tick{fill:#61747d;font:11px system-ui,sans-serif}.m-label{fill:#102a36;font:600 12px system-ui,sans-serif}.m-r{fill:none;stroke:#197f96;stroke-width:4}.m-s{fill:none;stroke:#bb5146;stroke-width:4}.m-rk{stroke:#d88b24;stroke-width:2;stroke-dasharray:7 5}.m-mean{stroke:#61747d;stroke-width:1.3;stroke-dasharray:3 5}.m-note{font:600 12px system-ui,sans-serif}.m-small{fill:#61747d;font:11px system-ui,sans-serif}\n          </style>\n          ${ticks.map(t => `<line x1=\"${x(t)}\" y1=\"${margin.top}\" x2=\"${x(t)}\" y2=\"${baseY}\" class=\"m-grid\"/><text x=\"${x(t)}\" y=\"${baseY + 20}\" text-anchor=\"middle\" class=\"m-tick\">${fmt(t, 1)}</text>`).join(\"\")}\n          <line x1=\"${margin.left}\" y1=\"${baseY}\" x2=\"${width - margin.right}\" y2=\"${baseY}\" class=\"m-axis\"/>\n          <path d=\"${makePath(p.meanR, p.stdR, rk, upper, true)}\" fill=\"url(#r95Fill)\"/>\n          <path d=\"${makePath(p.meanR, p.stdR, lower, rk, true)}\" fill=\"url(#r5Hatch)\"/>\n          <path d=\"${makePath(p.meanR, p.stdR)}\" class=\"m-r\"/>\n          <path d=\"${makePath(p.meanS, p.stdS)}\" class=\"m-s\"/>\n          <line x1=\"${x(rk)}\" y1=\"${y(normalPDF(rk, p.meanR, p.stdR))}\" x2=\"${x(rk)}\" y2=\"${baseY}\" class=\"m-rk\"/>\n          <line x1=\"${x(p.meanR)}\" y1=\"${y(normalPDF(p.meanR, p.meanR, p.stdR))}\" x2=\"${x(p.meanR)}\" y2=\"${baseY}\" class=\"m-mean\"/>\n          <line x1=\"${x(p.meanS)}\" y1=\"${y(normalPDF(p.meanS, p.meanS, p.stdS))}\" x2=\"${x(p.meanS)}\" y2=\"${baseY}\" class=\"m-mean\"/>\n          <text x=\"${x(p.meanR) + 10}\" y=\"${margin.top + 30}\" fill=\"#197f96\" class=\"m-note\">抗力 R</text>\n          <text x=\"${x(p.meanS) - 10}\" y=\"${margin.top + 58}\" text-anchor=\"end\" fill=\"#bb5146\" class=\"m-note\">荷载 S</text>\n          <text x=\"${x(rk) - 7}\" y=\"${baseY - 10}\" text-anchor=\"end\" fill=\"#d88b24\" class=\"m-note\">Rₖ = μᵣ − 1.645σᵣ</text>\n          <text x=\"${x((rk + upper) / 2)}\" y=\"${baseY - 34}\" text-anchor=\"middle\" fill=\"#197f96\" class=\"m-note\">95%</text>\n          <line x1=\"${x(p.meanR)}\" y1=\"${margin.top + 78}\" x2=\"${x(p.meanR - p.stdR)}\" y2=\"${margin.top + 78}\" stroke=\"#197f96\" stroke-width=\"2\" marker-end=\"url(#arrowCyan)\"/>\n          <text x=\"${x(p.meanR - p.stdR / 2)}\" y=\"${margin.top + 69}\" text-anchor=\"middle\" fill=\"#197f96\" class=\"m-small\">抗力向小处偏</text>\n          <line x1=\"${x(p.meanS)}\" y1=\"${margin.top + 104}\" x2=\"${x(p.meanS + p.stdS)}\" y2=\"${margin.top + 104}\" stroke=\"#bb5146\" stroke-width=\"2\" marker-end=\"url(#arrowCoral)\"/>\n          <text x=\"${x(p.meanS + p.stdS / 2)}\" y=\"${margin.top + 125}\" text-anchor=\"middle\" fill=\"#bb5146\" class=\"m-small\">荷载向大处偏</text>\n          <text x=\"${margin.left + plotW / 2}\" y=\"${height - 12}\" text-anchor=\"middle\" class=\"m-label\">同一量纲下的抗力与荷载</text>`;\n      }\n\n      function renderSurface(p) {\n        const canvas = $(\"surfacePlot\");\n        const rect = canvas.getBoundingClientRect();\n        const width = Math.max(300, rect.width || 900);\n        const height = Math.max(260, rect.height || 460);\n        const dpr = Math.min(window.devicePixelRatio || 1, 2);\n        canvas.width = Math.round(width * dpr);\n        canvas.height = Math.round(height * dpr);\n        const ctx = canvas.getContext(\"2d\");\n        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n        ctx.clearRect(0, 0, width, height);\n\n        const lowerRaw = Math.min(p.meanR - 3.6 * p.stdR, p.meanS - 3.6 * p.stdS);\n        const upperRaw = Math.max(p.meanR + 3.6 * p.stdR, p.meanS + 3.6 * p.stdS);\n        const spread = Math.max(upperRaw - lowerRaw, 2);\n        const lower = lowerRaw - spread * .04;\n        const upper = upperRaw + spread * .04;\n        const span = upper - lower;\n        const originX = width * .5;\n        const originY = height * .70;\n        const scale = Math.min(width * .31, height * .35) * state.surfaceView.zoom;\n        const maxDensity = jointDensity(p, p.meanS, p.meanR);\n        const project = (s, r, density = 0) => {\n          const x = ((s - lower) / span - .5) * 2;\n          const z = ((r - lower) / span - .5) * 2;\n          const y = density / maxDensity * .90;\n          const cy = Math.cos(state.surfaceView.yaw);\n          const sy = Math.sin(state.surfaceView.yaw);\n          const cp = Math.cos(state.surfaceView.pitch);\n          const sp = Math.sin(state.surfaceView.pitch);\n          const rotatedX = x * cy - z * sy;\n          const rotatedZ = x * sy + z * cy;\n          const rotatedY = y * cp - rotatedZ * sp;\n          const depth = y * sp + rotatedZ * cp;\n          return {\n            x: originX + rotatedX * scale,\n            y: originY - rotatedY * scale,\n            depth\n          };\n        };\n        const poly = (points, fill, stroke = \"rgba(16,42,54,.14)\", lineWidth = .7) => {\n          ctx.beginPath();\n          points.forEach((point, index) => index ? ctx.lineTo(point.x, point.y) : ctx.moveTo(point.x, point.y));\n          ctx.closePath();\n          ctx.fillStyle = fill;\n          ctx.fill();\n          if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth; ctx.stroke(); }\n        };\n\n        const p00 = project(lower, lower), p10 = project(upper, lower), p11 = project(upper, upper), p01 = project(lower, upper);\n        poly([p00, p10, p11, p01], \"rgba(255,255,255,.82)\", \"rgba(97,116,125,.35)\", 1);\n        poly([p00, p10, p11], \"rgba(187,81,70,.12)\", null);\n        poly([p00, p11, p01], \"rgba(25,127,150,.10)\", null);\n\n        ctx.save();\n        ctx.strokeStyle = \"rgba(97,116,125,.17)\";\n        ctx.lineWidth = 1;\n        for (let i = 0; i <= 5; i++) {\n          const value = lower + span * i / 5;\n          const a = project(value, lower), b = project(value, upper);\n          const c = project(lower, value), d = project(upper, value);\n          ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();\n          ctx.beginPath(); ctx.moveTo(c.x, c.y); ctx.lineTo(d.x, d.y); ctx.stroke();\n        }\n        ctx.restore();\n\n        const n = width < 520 ? 26 : 34;\n        const cells = [];\n        for (let i = 0; i < n; i++) {\n          for (let j = 0; j < n; j++) {\n            const s0 = lower + span * i / n, s1 = lower + span * (i + 1) / n;\n            const r0 = lower + span * j / n, r1 = lower + span * (j + 1) / n;\n            const d00 = jointDensity(p, s0, r0), d10 = jointDensity(p, s1, r0);\n            const d11 = jointDensity(p, s1, r1), d01 = jointDensity(p, s0, r1);\n            const avg = (d00 + d10 + d11 + d01) / 4;\n            const points = [project(s0, r0, d00), project(s1, r0, d10), project(s1, r1, d11), project(s0, r1, d01)];\n            cells.push({\n              depth: points.reduce((sum, point) => sum + point.depth, 0) / points.length,\n              failed: (s0 + s1) > (r0 + r1),\n              height: avg / maxDensity,\n              points\n            });\n          }\n        }\n        cells.sort((a, b) => a.depth - b.depth);\n        for (const cell of cells) {\n          const alpha = .32 + .54 * Math.pow(cell.height, .42);\n          const fill = cell.failed\n            ? `rgba(187,81,70,${alpha})`\n            : `rgba(25,127,150,${alpha})`;\n          poly(cell.points, fill, \"rgba(255,255,255,.24)\", .55);\n        }\n\n        const boundaryA = project(lower, lower), boundaryB = project(upper, upper);\n        ctx.beginPath(); ctx.moveTo(boundaryA.x, boundaryA.y); ctx.lineTo(boundaryB.x, boundaryB.y);\n        ctx.strokeStyle = \"rgba(133,48,42,.95)\"; ctx.lineWidth = 2; ctx.setLineDash([7,5]); ctx.stroke(); ctx.setLineDash([]);\n        ctx.beginPath();\n        for (let i = 0; i <= 64; i++) {\n          const value = lower + span * i / 64;\n          const point = project(value, value, jointDensity(p, value, value));\n          if (i === 0) ctx.moveTo(point.x, point.y); else ctx.lineTo(point.x, point.y);\n        }\n        ctx.strokeStyle = \"rgba(133,48,42,.96)\";\n        ctx.lineWidth = 2.6;\n        ctx.stroke();\n        const meanTop = project(p.meanS, p.meanR, maxDensity);\n        ctx.beginPath(); ctx.arc(meanTop.x, meanTop.y, 4.5, 0, Math.PI * 2); ctx.fillStyle = \"#d88b24\"; ctx.fill();\n\n        const drawBadge = (point, text, foreground, background) => {\n          ctx.save();\n          ctx.font = `700 ${width < 520 ? 10 : 12}px \"Microsoft YaHei\", sans-serif`;\n          const boxWidth = ctx.measureText(text).width + 18;\n          const boxHeight = width < 520 ? 25 : 29;\n          const x = clamp(point.x - boxWidth / 2, 5, width - boxWidth - 5);\n          const y = clamp(point.y - boxHeight / 2, 76, height - boxHeight - 5);\n          ctx.beginPath();\n          ctx.roundRect(x, y, boxWidth, boxHeight, 7);\n          ctx.fillStyle = background;\n          ctx.fill();\n          ctx.strokeStyle = foreground;\n          ctx.lineWidth = 1.2;\n          ctx.stroke();\n          ctx.fillStyle = foreground;\n          ctx.textAlign = \"center\";\n          ctx.textBaseline = \"middle\";\n          ctx.fillText(text, x + boxWidth / 2, y + boxHeight / 2 + .5);\n          ctx.restore();\n        };\n        drawBadge(project(lower + span * .25, lower + span * .75), \"安全侧  R ≥ S\", \"#176f87\", \"rgba(229,246,248,.94)\");\n        drawBadge(project(lower + span * .75, lower + span * .25), \"失效侧  R < S\", \"#9e433a\", \"rgba(255,235,231,.95)\");\n\n        ctx.fillStyle = \"#102a36\";\n        ctx.font = `${width < 520 ? 10 : 12}px \"Microsoft YaHei\", sans-serif`;\n        ctx.textAlign = \"center\";\n        ctx.fillText(\"R = S 临界线\", (boundaryA.x + boundaryB.x) / 2 + 34, (boundaryA.y + boundaryB.y) / 2 - 8);\n        ctx.fillText(\"荷载 S\", p10.x + (width < 520 ? -8 : 16), p10.y + 24);\n        ctx.fillText(\"抗力 R\", p01.x + (width < 520 ? 8 : -16), p01.y + 24);\n        ctx.fillStyle = \"#61747d\";\n        ctx.textAlign = \"left\";\n        ctx.fillText(\"联合概率密度\", 14, 22);\n        ctx.fillText(`方位 ${Math.round(state.surfaceView.yaw * 180 / Math.PI)}° · 俯角 ${Math.round(state.surfaceView.pitch * 180 / Math.PI)}°`, 14, 42);\n      }\n\n      function axisTicks(min, max, count = 5) {\n        const raw = (max - min) / count;\n        const magnitude = Math.pow(10, Math.floor(Math.log10(raw || 1)));\n        const normalized = raw / magnitude;\n        const step = (normalized <= 1 ? 1 : normalized <= 2 ? 2 : normalized <= 5 ? 5 : 10) * magnitude;\n        const first = Math.ceil(min / step) * step;\n        const ticks = [];\n        for (let value = first; value <= max + step * .001; value += step) ticks.push(value);\n        return ticks;\n      }\n      function renderJoint(p, sampled) {\n        const svg = $(\"jointPlot\");\n        const margin = { left: 61, right: 25, top: 22, bottom: 54 };\n        const width = 600, height = 420;\n        const plotW = width - margin.left - margin.right;\n        const plotH = height - margin.top - margin.bottom;\n        const lowerRaw = Math.min(p.meanR - 3.8 * p.stdR, p.meanS - 3.8 * p.stdS);\n        const upperRaw = Math.max(p.meanR + 3.8 * p.stdR, p.meanS + 3.8 * p.stdS);\n        const spread = Math.max(upperRaw - lowerRaw, 2);\n        const lower = lowerRaw - spread * .04;\n        const upper = upperRaw + spread * .04;\n        const x = (value) => margin.left + (value - lower) / (upper - lower) * plotW;\n        const y = (value) => margin.top + (upper - value) / (upper - lower) * plotH;\n        const ticks = axisTicks(lower, upper, 5);\n        const grid = ticks.map(t => `<line x1=\"${x(t)}\" y1=\"${margin.top}\" x2=\"${x(t)}\" y2=\"${margin.top + plotH}\" class=\"grid-line\"/><line x1=\"${margin.left}\" y1=\"${y(t)}\" x2=\"${margin.left + plotW}\" y2=\"${y(t)}\" class=\"grid-line\"/><text x=\"${x(t)}\" y=\"${margin.top + plotH + 25}\" class=\"tick\" text-anchor=\"middle\">${fmt(t, t < 10 ? 1 : 0)}</text><text x=\"${margin.left - 10}\" y=\"${y(t) + 4}\" class=\"tick\" text-anchor=\"end\">${fmt(t, t < 10 ? 1 : 0)}</text>`).join(\"\");\n        const root = Math.sqrt(Math.max(0, 1 - p.rho * p.rho));\n        const contours = [.75, 1.25, 1.75, 2.25, 2.75].map((radius, contourIndex) => {\n          const path = [];\n          for (let i = 0; i <= 120; i++) {\n            const angle = Math.PI * 2 * i / 120;\n            const u = radius * Math.cos(angle);\n            const v = radius * Math.sin(angle);\n            const s = p.meanS + p.stdS * u;\n            const r = p.meanR + p.stdR * (p.rho * u + root * v);\n            path.push(`${i ? \"L\" : \"M\"} ${x(s)} ${y(r)}`);\n          }\n          return `<path d=\"${path.join(\" \")}\" class=\"contour contour-${contourIndex}\"/>`;\n        }).join(\"\");\n        const points = sampled.shown.map(point => point.failed\n          ? `<path d=\"M ${x(point.s) - 2.4} ${y(point.r) - 2.4} l 4.8 4.8 m -4.8 0 l 4.8 -4.8\" class=\"point-fail\"/>`\n          : `<circle cx=\"${x(point.s)}\" cy=\"${y(point.r)}\" r=\"2\" class=\"point-safe\"/>`\n        ).join(\"\");\n        svg.innerHTML = `\n          <title id=\"jointTitle\">抗力与荷载随机样本散点图</title>\n          <desc id=\"jointDesc\">共显示 ${sampled.shown.length} 个样本，其中红色叉号表示荷载大于抗力。</desc>\n          <defs>\n            <pattern id=\"failureHatch\" width=\"9\" height=\"9\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\"><rect width=\"9\" height=\"9\" fill=\"#f8dfdc\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"9\" stroke=\"#d8958e\" stroke-width=\"2\"/></pattern>\n            <clipPath id=\"jointClip\"><rect x=\"${margin.left}\" y=\"${margin.top}\" width=\"${plotW}\" height=\"${plotH}\"/></clipPath>\n          </defs>\n          <style>\n            .grid-line{stroke:#dce4e6;stroke-width:1}.axis-line{stroke:#61747d;stroke-width:1.2}.tick{fill:#61747d;font:11px system-ui,sans-serif}.axis-label{fill:#102a36;font:600 12px system-ui,sans-serif}.boundary{stroke:#bb5146;stroke-width:2;stroke-dasharray:7 6}.boundary-label{fill:#9e433a;font:600 11px system-ui,sans-serif}.contour{fill:none;stroke:#176f87;stroke-width:1.4;stroke-opacity:.72}.contour-0{stroke-width:2;stroke-opacity:.94}.mean-point{fill:#d88b24;stroke:#fff;stroke-width:2}.point-safe{fill:#197f96;fill-opacity:.38}.point-fail{fill:none;stroke:#a63f36;stroke-width:1.6;stroke-linecap:round}.region{fill:#dceff2}.region-fail{fill:url(#failureHatch)}.region-label{fill:#4e6873;font:600 11px system-ui,sans-serif}\n          </style>\n          <rect x=\"${margin.left}\" y=\"${margin.top}\" width=\"${plotW}\" height=\"${plotH}\" fill=\"#fff\"/>\n          <g clip-path=\"url(#jointClip)\">\n            <polygon points=\"${margin.left},${margin.top} ${margin.left + plotW},${margin.top} ${margin.left},${margin.top + plotH}\" class=\"region\"/>\n            <polygon points=\"${margin.left},${margin.top + plotH} ${margin.left + plotW},${margin.top + plotH} ${margin.left + plotW},${margin.top}\" class=\"region-fail\"/>\n             ${grid}\n            ${contours}\n             <line x1=\"${margin.left}\" y1=\"${margin.top + plotH}\" x2=\"${margin.left + plotW}\" y2=\"${margin.top}\" class=\"boundary\"/>\n             <g>${points}</g>\n            <circle cx=\"${x(p.meanS)}\" cy=\"${y(p.meanR)}\" r=\"5\" class=\"mean-point\"/>\n          </g>\n          <line x1=\"${margin.left}\" y1=\"${margin.top + plotH}\" x2=\"${margin.left + plotW}\" y2=\"${margin.top + plotH}\" class=\"axis-line\"/>\n          <line x1=\"${margin.left}\" y1=\"${margin.top}\" x2=\"${margin.left}\" y2=\"${margin.top + plotH}\" class=\"axis-line\"/>\n          <text x=\"${margin.left + plotW / 2}\" y=\"${height - 10}\" text-anchor=\"middle\" class=\"axis-label\">荷载 S</text>\n          <text x=\"17\" y=\"${margin.top + plotH / 2}\" text-anchor=\"middle\" class=\"axis-label\" transform=\"rotate(-90 17 ${margin.top + plotH / 2})\">抗力 R</text>\n          <text x=\"${x(lower + spread * .18)}\" y=\"${y(upper - spread * .14)}\" class=\"region-label\">抗力尚有余地</text>\n          <text x=\"${x(upper - spread * .19)}\" y=\"${y(lower + spread * .12)}\" text-anchor=\"end\" class=\"boundary-label\">荷载越过抗力</text>\n          <text x=\"${x(upper - spread * .08)}\" y=\"${y(upper - spread * .04)}\" text-anchor=\"end\" class=\"boundary-label\">R = S</text>`;\n        $(\"shownPoints\").textContent = `图中显示 ${sampled.shown.length.toLocaleString(\"zh-CN\")} 点；统计使用全部 ${p.n.toLocaleString(\"zh-CN\")} 点`;\n      }\n\n      function renderGap(t) {\n        const svg = $(\"gapPlot\");\n        const margin = { left: 61, right: 25, top: 22, bottom: 54 };\n        const width = 600, height = 420;\n        const plotW = width - margin.left - margin.right;\n        const plotH = height - margin.top - margin.bottom;\n        const lowerRaw = Math.min(0, t.meanZ - 4.2 * t.stdZ);\n        const upperRaw = Math.max(0, t.meanZ + 4.2 * t.stdZ);\n        const spread = Math.max(upperRaw - lowerRaw, 2);\n        const lower = lowerRaw - spread * .04;\n        const upper = upperRaw + spread * .04;\n        const maxPdf = normalPDF(t.meanZ, t.meanZ, t.stdZ) * 1.08;\n        const x = (value) => margin.left + (value - lower) / (upper - lower) * plotW;\n        const y = (value) => margin.top + plotH - value / maxPdf * plotH;\n        const ticks = axisTicks(lower, upper, 6);\n        const grid = ticks.map(value => `<line x1=\"${x(value)}\" y1=\"${margin.top}\" x2=\"${x(value)}\" y2=\"${margin.top + plotH}\" class=\"grid-line\"/><text x=\"${x(value)}\" y=\"${margin.top + plotH + 25}\" class=\"tick\" text-anchor=\"middle\">${fmt(value, Math.abs(value) < 10 ? 1 : 0)}</text>`).join(\"\");\n        const count = 180;\n        const line = [];\n        const failArea = [`M ${x(lower)} ${y(0)}`];\n        const safeArea = [`M ${x(Math.max(0, lower))} ${y(0)}`];\n        for (let i = 0; i <= count; i++) {\n          const value = lower + (upper - lower) * i / count;\n          const py = y(normalPDF(value, t.meanZ, t.stdZ));\n          line.push(`${i === 0 ? \"M\" : \"L\"} ${x(value)} ${py}`);\n          if (value <= 0) failArea.push(`L ${x(value)} ${py}`);\n          if (value >= 0) safeArea.push(`L ${x(value)} ${py}`);\n        }\n        failArea.push(`L ${x(Math.min(0, upper))} ${y(0)} Z`);\n        safeArea.push(`L ${x(upper)} ${y(0)} Z`);\n        const zeroX = x(0);\n        const meanX = x(t.meanZ);\n        svg.innerHTML = `\n          <title id=\"gapTitle\">抗力减荷载的概率密度图</title>\n          <desc id=\"gapDesc\">零左侧的理论概率为 ${probabilityText(t.pf)}，可靠指标为 ${fmt(t.beta, 3)}。</desc>\n          <defs><pattern id=\"gapHatch\" width=\"9\" height=\"9\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\"><rect width=\"9\" height=\"9\" fill=\"#f8dfdc\"/><line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"9\" stroke=\"#d8958e\" stroke-width=\"2\"/></pattern></defs>\n          <style>\n            .grid-line{stroke:#e0e7e9;stroke-width:1}.axis-line{stroke:#61747d;stroke-width:1.2}.tick{fill:#61747d;font:11px system-ui,sans-serif}.axis-label{fill:#102a36;font:600 12px system-ui,sans-serif}.density{fill:none;stroke:#102a36;stroke-width:2.5}.safe-area{fill:#dceff2}.fail-area{fill:url(#gapHatch)}.zero{stroke:#bb5146;stroke-width:2;stroke-dasharray:7 6}.mean{stroke:#d88b24;stroke-width:2}.anno{fill:#4e6873;font:600 11px system-ui,sans-serif}.fail-label{fill:#9e433a;font:700 11px system-ui,sans-serif}\n          </style>\n          <rect x=\"${margin.left}\" y=\"${margin.top}\" width=\"${plotW}\" height=\"${plotH}\" fill=\"#fff\"/>\n          ${grid}\n          <path d=\"${safeArea.join(\" \")}\" class=\"safe-area\"/>\n          <path d=\"${failArea.join(\" \")}\" class=\"fail-area\"/>\n          <path d=\"${line.join(\" \")}\" class=\"density\"/>\n          <line x1=\"${zeroX}\" y1=\"${margin.top}\" x2=\"${zeroX}\" y2=\"${margin.top + plotH}\" class=\"zero\"/>\n          <line x1=\"${meanX}\" y1=\"${y(normalPDF(t.meanZ, t.meanZ, t.stdZ))}\" x2=\"${meanX}\" y2=\"${margin.top + plotH}\" class=\"mean\"/>\n          <line x1=\"${margin.left}\" y1=\"${margin.top + plotH}\" x2=\"${margin.left + plotW}\" y2=\"${margin.top + plotH}\" class=\"axis-line\"/>\n          <text x=\"${margin.left + plotW / 2}\" y=\"${height - 10}\" text-anchor=\"middle\" class=\"axis-label\">抗力 − 荷载（Z）</text>\n          <text x=\"${clamp(zeroX - 8, margin.left + 55, margin.left + plotW - 55)}\" y=\"${margin.top + 18}\" text-anchor=\"end\" class=\"fail-label\">Z &lt; 0：${probabilityText(t.pf)}</text>\n          <text x=\"${clamp(meanX + 7, margin.left + 55, margin.left + plotW - 80)}\" y=\"${margin.top + 38}\" class=\"anno\">平均差 ${fmt(t.meanZ, 2)}</text>\n          <text x=\"${zeroX + 6}\" y=\"${margin.top + plotH - 9}\" class=\"fail-label\">边界 0</text>`;\n      }\n\n      function updateOutputs(p) {\n        $(\"meanROut\").textContent = fmt(p.meanR, 1);\n        $(\"stdROut\").textContent = fmt(p.stdR, 2);\n        $(\"meanSOut\").textContent = fmt(p.meanS, 1);\n        $(\"stdSOut\").textContent = fmt(p.stdS, 2);\n        $(\"rhoOut\").textContent = (p.rho > 0 ? \"+\" : \"\") + fmt(p.rho, 2);\n        $(\"seed\").value = p.seed;\n      }\n      function render() {\n        if (!document.body.isConnected || !$(\"betaValue\")) return;\n        const p = params();\n        updateOutputs(p);\n        const t = theory(p);\n        const sampled = sample(p);\n        renderMarginals(p);\n        renderSurface(p);\n        renderJoint(p, sampled);\n        renderGap(t);\n        const samplePf = sampled.failures / p.n;\n        $(\"betaValue\").textContent = fmt(t.beta, 3);\n        $(\"pfValue\").textContent = probabilityText(t.pf);\n        $(\"sampleValue\").textContent = `${sampled.failures.toLocaleString(\"zh-CN\")} / ${p.n.toLocaleString(\"zh-CN\")}`;\n        $(\"ciValue\").textContent = `${probabilityText(sampled.ci[0])} – ${probabilityText(sampled.ci[1])}`;\n        const expected = t.pf * p.n;\n        const ciContainsTheory = t.pf >= sampled.ci[0] && t.pf <= sampled.ci[1];\n        $(\"sampleExplain\").innerHTML = `按理论失效概率估计，${p.n.toLocaleString(\"zh-CN\")} 个随机样本的期望失效次数约为 <strong>${fmt(expected, expected < 10 ? 1 : 0)} 次</strong>；本次抽样得到 ${sampled.failures.toLocaleString(\"zh-CN\")} 次。${ciContainsTheory ? \"理论值位于样本比例的 95% 置信区间内；\" : \"理论值未位于样本比例的 95% 置信区间内；\"}改变随机种子会改变有限样本统计量，但不改变给定概率模型的理论值。`;\n        $(\"formulaNote\").innerHTML = Math.abs(p.rho) < 1e-12\n          ? `当前取 ρ = 0，R 与 S 相互独立，所以 σ<sub>Z</sub> = √(σ<sub>R</sub>² + σ<sub>S</sub>²) = ${fmt(t.stdZ, 3)}。“可靠指标 β”就是均值差里能放下多少个“差值的标准差”；P<sub>f</sub> = Φ(−β) 是 Z &lt; 0 的理论概率。`\n          : `当前取 ρ = ${fmt(p.rho, 2)}，所以 σ<sub>Z</sub> = √(σ<sub>R</sub>² + σ<sub>S</sub>² − 2ρσ<sub>R</sub>σ<sub>S</sub>) = ${fmt(t.stdZ, 3)}。相关性先改变差值的波动，再改变 β 与 P<sub>f</sub>。`;\n        $(\"predictionReturn\").textContent = `当前参数下，联合分布位于失效域中的理论概率质量为 ${probabilityText(t.pf)}。可保持均值不变并改变标准差，比较分布展宽与可靠指标的变化。`;\n        $(\"liveSummary\").textContent = `理论可靠指标 ${fmt(t.beta, 3)}，理论失效概率 ${probabilityText(t.pf)}；样本 ${p.n} 次中失效 ${sampled.failures} 次，Wilson 百分之九十五区间 ${probabilityText(sampled.ci[0])} 到 ${probabilityText(sampled.ci[1])}。`;\n        reportHeight();\n      }\n      function scheduleRender() {\n        if (state.framePending) return;\n        state.framePending = true;\n        requestAnimationFrame(() => { state.framePending = false; render(); });\n      }\n      function scheduleSurfaceRender() {\n        if (state.surfacePending) return;\n        state.surfacePending = true;\n        requestAnimationFrame(() => {\n          state.surfacePending = false;\n          renderSurface(params());\n        });\n      }\n      function resetSurfaceView() {\n        Object.assign(state.surfaceView, defaultSurfaceView);\n        scheduleSurfaceRender();\n      }\n      function setValues(values) {\n        Object.entries(values).forEach(([id, value]) => { if ($(id)) $(id).value = value; });\n        scheduleRender();\n      }\n      function reportHeight() {\n        if (window.parent === window) return;\n        requestAnimationFrame(() => {\n          const height = Math.ceil(document.documentElement.scrollHeight);\n          window.parent.postMessage({\n            source: \"bridge-interaction-shell\",\n            type: \"resize\",\n            height,\n            layout: \"flow\"\n          }, \"*\");\n        });\n      }\n\n      const surfaceCanvas = $(\"surfacePlot\");\n      surfaceCanvas.addEventListener(\"pointerdown\", event => {\n        if (event.button !== 0) return;\n        event.preventDefault();\n        surfaceCanvas.focus({ preventScroll: true });\n        surfaceCanvas.setPointerCapture(event.pointerId);\n        surfaceCanvas.classList.add(\"is-dragging\");\n        state.surfaceDrag = { pointerId: event.pointerId, x: event.clientX, y: event.clientY };\n      });\n      surfaceCanvas.addEventListener(\"pointermove\", event => {\n        const drag = state.surfaceDrag;\n        if (!drag || drag.pointerId !== event.pointerId) return;\n        const dx = event.clientX - drag.x;\n        const dy = event.clientY - drag.y;\n        drag.x = event.clientX;\n        drag.y = event.clientY;\n        state.surfaceView.yaw += dx * .008;\n        state.surfaceView.pitch = clamp(state.surfaceView.pitch - dy * .006, .22, 1.16);\n        scheduleSurfaceRender();\n      });\n      const stopSurfaceDrag = event => {\n        if (!state.surfaceDrag || state.surfaceDrag.pointerId !== event.pointerId) return;\n        state.surfaceDrag = null;\n        surfaceCanvas.classList.remove(\"is-dragging\");\n      };\n      surfaceCanvas.addEventListener(\"pointerup\", stopSurfaceDrag);\n      surfaceCanvas.addEventListener(\"pointercancel\", stopSurfaceDrag);\n      surfaceCanvas.addEventListener(\"lostpointercapture\", () => {\n        state.surfaceDrag = null;\n        surfaceCanvas.classList.remove(\"is-dragging\");\n      });\n      surfaceCanvas.addEventListener(\"wheel\", event => {\n        event.preventDefault();\n        state.surfaceView.zoom = clamp(state.surfaceView.zoom * Math.exp(-event.deltaY * .0012), .72, 1.65);\n        scheduleSurfaceRender();\n      }, { passive: false });\n      surfaceCanvas.addEventListener(\"keydown\", event => {\n        const step = event.shiftKey ? .18 : .08;\n        if (event.key === \"ArrowLeft\") state.surfaceView.yaw -= step;\n        else if (event.key === \"ArrowRight\") state.surfaceView.yaw += step;\n        else if (event.key === \"ArrowUp\") state.surfaceView.pitch = clamp(state.surfaceView.pitch + step, .22, 1.16);\n        else if (event.key === \"ArrowDown\") state.surfaceView.pitch = clamp(state.surfaceView.pitch - step, .22, 1.16);\n        else if (event.key === \"+\" || event.key === \"=\") state.surfaceView.zoom = clamp(state.surfaceView.zoom * 1.08, .72, 1.65);\n        else if (event.key === \"-\" || event.key === \"_\") state.surfaceView.zoom = clamp(state.surfaceView.zoom / 1.08, .72, 1.65);\n        else if (event.key === \"0\" || event.key === \"Home\") resetSurfaceView();\n        else return;\n        event.preventDefault();\n        scheduleSurfaceRender();\n      });\n      surfaceCanvas.addEventListener(\"dblclick\", resetSurfaceView);\n      $(\"resetSurfaceView\").addEventListener(\"click\", resetSurfaceView);\n      parameterIds.forEach(id => $(id).addEventListener(id === \"sampleN\" ? \"change\" : \"input\", scheduleRender));\n      $(\"nextSeed\").addEventListener(\"click\", () => {\n        $(\"seed\").value = clamp((+$(\"seed\").value || 1) + 1, 1, 999999);\n        render();\n      });\n      document.querySelectorAll(\"[data-preset]\").forEach(button => {\n        button.addEventListener(\"click\", () => {\n          const presets = {\n            stable: { meanR: 10, stdR: .75, meanS: 6, stdS: .6, rho: 0 },\n            default: { meanR: 10, stdR: 1.5, meanS: 6, stdS: 1.2, rho: 0 },\n            close: { meanR: 8, stdR: 1.5, meanS: 7, stdS: 1.2, rho: 0 },\n            together: { meanR: 10, stdR: 1.5, meanS: 6, stdS: 1.2, rho: .7 }\n          };\n          setValues(presets[button.dataset.preset]);\n        });\n      });\n      $(\"advancedViews\").addEventListener(\"toggle\", () => {\n        scheduleRender();\n        reportHeight();\n      });\n      addEventListener(\"resize\", () => { scheduleRender(); reportHeight(); }, { passive: true });\n      new ResizeObserver(reportHeight).observe(document.body);\n      render();\n      reportHeight();\n\n      window.__reliabilityLabTest = {\n        normalCDF,\n        theory,\n        wilsonInterval,\n        surfaceView: () => ({ ...state.surfaceView }),\n        defaultPoint: () => theory({ meanR: 10, stdR: 1.5, meanS: 6, stdS: 1.2, rho: 0 })\n      };\n    })();\n  </script>\n  <script src=\"./learning-cycle.js?v=20260809b\"></script>\n\n\n\n</body>\n</html>\n"}, {"name": "interactive/learning-cycle.js", "text": "/*\n * 数字教材兼容层：旧资源曾在此注入“先预测—再揭示”的对话模块。\n * 本书采用正文中的“对象—公式—参数—结果—边界”结构，因此移除空挂载位，\n * 保留原计算与可视化代码，不增加对话式提示。\n */\ndocument.querySelectorAll('[data-learning-cycle-mount]').forEach((node) => node.remove());\n"}];
